#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <setjmp.h>
#include <dlfcn.h>

typedef void* j_common_ptr;
struct jpeg_error_mgr_min {
  void (*error_exit)(j_common_ptr);
  void (*emit_message)(j_common_ptr,int);
  void (*output_message)(j_common_ptr);
  void (*format_message)(j_common_ptr,char*);
  void (*reset_error_mgr)(j_common_ptr);
  int msg_code;
  union { int i[8]; char s[80]; } msg_parm;
  int trace_level; long num_warnings;
  const char * const *jpeg_message_table; int last_jpeg_message;
  const char * const *addon_message_table; int first_addon_message; int last_addon_message;
};
struct common_min { struct jpeg_error_mgr_min *err; void *mem,*progress,*client_data; int is_decompressor; int global_state; };
static jmp_buf jb;
static void my_error_exit(j_common_ptr cinfo){ longjmp(jb,1); }
int main(){
 void *h=dlopen("libjpeg.so.8",RTLD_LAZY); if(!h){perror("dlopen"); return 1;}
 struct jpeg_error_mgr_min* (*jpeg_std_error)(struct jpeg_error_mgr_min*)=dlsym(h,"jpeg_std_error");
 void (*jpeg_CreateDecompress)(void*,int,size_t)=dlsym(h,"jpeg_CreateDecompress");
 void (*jpeg_destroy_decompress)(void*)=dlsym(h,"jpeg_destroy_decompress");
 for(int ver=50; ver<=100; ver++){
  for(size_t sz=128; sz<=2048; sz+=8){
   unsigned char *buf=calloc(1,4096);
   struct common_min *c=(struct common_min*)buf;
   struct jpeg_error_mgr_min err;
   jpeg_std_error(&err); err.error_exit=my_error_exit; c->err=&err;
   if(setjmp(jb)==0){ jpeg_CreateDecompress(c,ver,sz); printf("ok ver=%d size=%zu\n",ver,sz); jpeg_destroy_decompress(c); free(buf); return 0; }
   free(buf);
  }
 }
 puts("none"); return 2;
}
EOF
