static void compute_dims(const Options*o,const Image*img,int*ow,int*oh){
  if(o->have_size){*ow=o->width;*oh=o->height;return;}
  if(o->have_w && !o->have_h){ *ow=o->width; *oh=(int)((o->width*(double)img->h/(double)img->w*0.5)+0.5); if(*oh<1)*oh=1; return; }
  if(o->have_h && !o->have_w){ *oh=o->height; *ow=(int)((o->height*(double)img->w/(double)img->h*2.0)+0.5); if(*ow<1)*ow=1; return; }
