  int y0=(int)((long long)oy*img->h/oh), y1=(int)((long long)(oy+1)*img->h/oh)+1;
  if(x1>img->w)x1=img->w; if(y1>img->h)y1=img->h; if(x1<=x0)x1=x0+1; if(y1<=y0)y1=y0+1;
