static void html_escape_text(FILE*out,const char*s){ for(;*s;s++) html_escape_char(out,*s); }
static void ansi_color(FILE*out,Pixel p){ int r=p.r>127,g=p.g>127,b=p.b>127; int code=30 + (r?1:0) + (g?2:0) + (b?4:0); if(code!=37) fprintf(out,"\033[%dm",code); }
static void render_image(FILE*out,const Options*o,const Image*img,int ow,int oh,int html_body_only){
  if(o->clear && !o->html) fputs("\033[2J\033[0;0H",out);
  if(o->html && !o->html_raw && !html_body_only){
    fprintf(out,"<?xml version='1.0' encoding='ISO-8859-1'?>\n<!DOCTYPE html PUBLIC '-//W3C//DTD XHTML 1.0 Strict//EN'  'http://www.w3.org/TR/xhtml1/DTD/xhtml1-strict.dtd'>\n<html xmlns='http://www.w3.org/1999/xhtml' lang='en' xml:lang='en'>\n<head>\n<title>");
