          unsigned char br=o->invert?255-avg.r:avg.r, bg=o->invert?255-avg.g:avg.g, bb=o->invert?255-avg.b:avg.b;
          fprintf(out,"<span style='color:#%02x%02x%02x;", avg.r,avg.g,avg.b);
