  if(o->html && !o->html_raw && !html_body_only) fputs("</pre>\n</div>\n</body>\n</html>\n",out);
}
static void verbose_info(const char*name,const Image*img,const Options*o,int ow,int oh){
  fprintf(stderr,"File: %s\nSource width: %d\nSource height: %d\nSource color components: %d\nOutput width: %d\nOutput height: %d\nOutput palette (%d chars): '%s'\n", name,img->w,img->h,img->comps,ow,oh,o->nchar,o->chars);
  for(int i=1;i<=25;i++){ fprintf(stderr,"Decompressing image ["); int n=(int)(i*56/25.0+0.5); for(int j=0;j<n;j++)fputc('#',stderr); for(int j=n;j<56;j++)fputc('.',stderr); fprintf(stderr,"]\r"); } fprintf(stderr,"\n");
