int main(int argc,char**argv){
  Options opt; opt_init(&opt); int pr=parse_options(&opt,argc,argv); if(pr) return 1;
  FILE *out=stdout; if(opt.output && strcmp(opt.output,"-")!=0){ out=fopen(opt.output,"wb"); if(!out){ fprintf(stderr,"Can't open %s\n",opt.output); return 1; } }
  int status=0;
  for(int i=0;i<opt.ninputs;i++){
    unsigned char *buf=NULL; size_t sz=0; if(!read_file(opt.inputs[i],&buf,&sz)){ status=1; continue; }
    Image img={0}; if(!decode_jpeg(buf,sz,&img)){ free(buf); status=1; continue; } free(buf);
    int ow=0,oh=0; compute_dims(&opt,&img,&ow,&oh); if(ow<=0||oh<=0){ free(img.pix); if(out!=stdout)fclose(out); return 1; }
    if(opt.verbose) verbose_info(opt.inputs[i],&img,&opt,ow,oh);
    render_image(out,&opt,&img,ow,oh,0); free(img.pix);
  }
  if(out!=stdout) fclose(out); return status?1:0;
}
