static void opt_init(Options *o){
  memset(o,0,sizeof(*o));
  o->chars=strdup("   ...',;:clodxkO0KXNWM"); o->nchar=strlen(o->chars);
  o->rw=0.2989; o->gw=0.5866; o->bw=0.1145; o->fontsize=4;
