static int starts(const char*s,const char*p){return strncmp(s,p,strlen(p))==0;}
static const char *need_arg(int *i,int argc,char **argv,const char *opt){
  if(*i+1>=argc){ fprintf(stderr,"Unknown option %s\n\n%s",opt,HELP_TEXT); exit(1); }
  return argv[++*i];
}
static int parse_int_pos(const char *s){ char *e; long v=strtol(s,&e,10); if(e==s||*e) return -1; return (int)v; }
static double parse_double(const char*s){ char*e; double v=strtod(s,&e); if(e==s||*e) return NAN; return v; }
static void parse_size(Options*o,const char*v,const char*orig){
  char *x=strchr(v,'x'); if(!x) x=strchr(v,'X');
  if(!x){ fprintf(stderr,"Unknown option %s\n\n%s",orig,HELP_TEXT); exit(1); }
  char a[64],b[64]; size_t la=x-v; if(la>=sizeof(a)) la=sizeof(a)-1; memcpy(a,v,la); a[la]=0; snprintf(b,sizeof(b),"%s",x+1);
