static int parse_options(Options*o,int argc,char**argv){
  for(int i=1;i<argc;i++){
    char *a=argv[i];
    if(strcmp(a,"--help")==0 || strcmp(a,"-h")==0){ fputs(HELP_TEXT,stdout); exit(0); }
    if(strcmp(a,"--version")==0 || strcmp(a,"-V")==0){ fputs(VERSION_TEXT,stdout); exit(0); }
