    if(starts(a,"--width=")) val=a+8; else if(strcmp(a,"--width")==0) val=need_arg(&i,argc,argv,a);
    if(val){ int w=parse_int_pos(val); if(w>0){o->width=w;o->have_w=1;o->have_size=0;o->term_fit=0;} continue; }
    if(starts(a,"--height=")) val=a+9; else if(strcmp(a,"--height")==0) val=need_arg(&i,argc,argv,a);
    if(val){ int h=parse_int_pos(val); if(h>0){o->height=h;o->have_h=1;o->have_size=0;o->term_fit=0;} continue; }
    if(starts(a,"--output=")) val=a+9; else if(strcmp(a,"--output")==0) val=need_arg(&i,argc,argv,a);
    if(val){ free(o->output); o->output=strdup(val); continue; }
    if(starts(a,"--red=")) val=a+6; else if(strcmp(a,"--red")==0) val=need_arg(&i,argc,argv,a); if(val){ o->rw=parse_double(val); continue; }
    if(starts(a,"--green=")) val=a+8; else if(strcmp(a,"--green")==0) val=need_arg(&i,argc,argv,a); if(val){ o->gw=parse_double(val); continue; }
    if(starts(a,"--blue=")) val=a+7; else if(strcmp(a,"--blue")==0) val=need_arg(&i,argc,argv,a); if(val){ o->bw=parse_double(val); continue; }
    if(starts(a,"--html-fontsize=")) val=a+16; else if(strcmp(a,"--html-fontsize")==0) val=need_arg(&i,argc,argv,a); if(val){ int n=parse_int_pos(val); if(n>0)o->fontsize=n; continue; }
    if(starts(a,"--html-title=")) val=a+13; else if(strcmp(a,"--html-title")==0) val=need_arg(&i,argc,argv,a); if(val){ free(o->html_title); o->html_title=strdup(val); continue; }
    if(strcmp(a,"--border")==0){o->border=1;continue;} if(strcmp(a,"--debug")==0){o->debug=1;continue;}
