    if(strcmp(a,"--invert")==0){o->invert=!o->invert;continue;} if(strcmp(a,"--verbose")==0){o->verbose=1;continue;}
    if(strcmp(a,"--clear")==0){o->clear=1;continue;} if(strcmp(a,"--colors")==0 || strcmp(a,"--color")==0){o->colors=1;continue;}
    if(strcmp(a,"--grayscale")==0){o->grayscale=1;continue;} if(strcmp(a,"--html")==0){o->html=1;continue;}
    if(strcmp(a,"--html-raw")==0){o->html_raw=1;continue;} if(strcmp(a,"--html-no-bold")==0){o->html_no_bold=1;continue;}
    if(strcmp(a,"--fill")==0){o->fill=o->html_fill=1;continue;} if(strcmp(a,"--html-fill")==0){o->fill=o->html_fill=1;continue;}
    if(strcmp(a,"--term-fit")==0){o->term_fit=1;o->have_w=o->have_h=o->have_size=0;continue;}
    if(strcmp(a,"--term-width")==0){o->term_width=1;continue;} if(strcmp(a,"--term-height")==0){o->term_height=1;continue;}
