  if(fabs((o->rw+o->gw+o->bw)-1.0)>0.0002){ fprintf(stderr,"Weights RED + GREEN + BLUE must equal 1.0\n"); return 1; }
  return 0;
}

static int read_file(const char *name, unsigned char **out, size_t *sz){
  FILE *f;
  if(strcmp(name,"-")==0) f=stdin;
  else {
    if(starts(name,"file://")) name+=7;
    if(strstr(name,"://") && !starts(name,"file://")){ fprintf(stderr,"Couldn't download %s\n",name); return 0; }
